#include "RoamCore.h"
#include <stdio.h>
#include <stdlib.h>
struct World {int x=0,y=0,requests=0,checks=0;bool wall=false,accept=true,freeze=false,empty=false;};
static void check(bool p,const char* s){if(!p){printf("FAIL %s\n",s);exit(1);}printf("PASS %s\n",s);}
static int __cdecl pass(void* p,int,int x,int y,int nx,int ny){auto& w=*(World*)p;++w.checks;if(w.empty)return 0;if(abs(nx)>12||abs(ny)>12)return 0;if(w.wall&&nx==1)return 0;if(w.wall&&x<1&&nx>1)return 0;if(abs(nx-x)>1||abs(ny-y)>1)return 0;return 1;}
static int __cdecl move(void* p,int,int x,int y){auto& w=*(World*)p;++w.requests;if(!w.accept)return 0;if(!w.freeze){w.x=x;w.y=y;}return 1;}
int main(){SRConfig c{12,2048,300,2000,12345};World w;SRHost h{&w,pass,move};SRState* s=sr_create(&c);SRInput i{1000,0,4,0,0,1,1,0,0};check(s!=nullptr,"create");check(sr_tick(s,&i,&h)==SR_STEP,"no-target starts reachable step");int n=w.requests;i.has_target=1;check(sr_tick(s,&i,&h)==SR_YIELD_TARGET&&w.requests==n,"target interrupts roaming");i.has_target=0;i.can_move=0;check(sr_tick(s,&i,&h)==SR_PAUSED&&w.requests==n,"stun pause without move");i.can_move=1;i.dead=1;check(sr_tick(s,&i,&h)==SR_PAUSED,"death resets route");i.dead=0;i.earliest_move_ms=99999;check(sr_tick(s,&i,&h)==SR_WAIT&&w.requests==n,"host move speed gate honored");i.earliest_move_ms=0;sr_reset(s);w=World{};w.wall=true;for(int k=0;k<2000;k++){i.now_ms+=100;i.x=w.x;i.y=w.y;int r=sr_tick(s,&i,&h);check(w.x<=0&&abs(w.y)<=12,"wall bounds");if(r==SR_INVALID)return 1;}check(w.requests>10,"long wall-side roaming continues");sr_reset(s);w=World{};w.empty=true;i.x=i.y=0;i.now_ms+=100;check(sr_tick(s,&i,&h)==SR_NO_ROUTE&&w.requests==0,"no reachable tile does not teleport");n=w.checks;i.now_ms+=10;check(sr_tick(s,&i,&h)==SR_WAIT&&w.checks==n,"no-route retry rate limited");sr_reset(s);w=World{};w.freeze=true;i.now_ms+=1000;check(sr_tick(s,&i,&h)==SR_STEP,"accepted move pending");i.now_ms+=100;check(sr_tick(s,&i,&h)==SR_WAIT&&w.requests==1,"pending move not spammed");i.now_ms+=2100;check(sr_tick(s,&i,&h)==SR_NO_ROUTE&&w.requests==1,"stuck move excluded and replanned");i.map=999;i.now_ms+=500;check(sr_tick(s,&i,&h)!=SR_INVALID,"map transition reset");check(sr_tick(nullptr,&i,&h)==SR_INVALID,"invalid state rejected");sr_destroy(s);printf("ALL ROAM TESTS PASS (synthetic host, not actual mjlin integration)\n");}
